/*
 * A331261  List of pairs of consecutive integers such that one of them is a
 *          square and their sum is also a square.
 * https://oeis.org/A331261
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 14, u32 n <= 26, u64 n <= 32, u128 n <= 32,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by merging pair solutions of the Pell equations
   s² - 2 t² = 1 (square on the lower integer) and
   s² - 2 t² = -1 (square on the upper integer).
   Each pair (x, x+1) is added to the sequence in order.
   The two families produce increasing sequences that interleave,
   so we compare the next x of each family and output the smaller one first.
   Each pair contributes its two integers in order. */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* The function is robust for any order of calls; it produces terms
       on demand by iterating the two Pell sequences. */
    idx_t count = 0;      /* number of terms produced so far */
    seq_t result = 0;

    /* Variables for the negative Pell family: s² - 2 t² = -1 */
    seq_t s_neg = (seq_t)1, t_neg = (seq_t)1;

    /* Variables for the positive Pell family: s² - 2 t² = 1 */
    seq_t s_pos = (seq_t)3, t_pos = (seq_t)2;

    /* Produce terms until the required n-th term is reached */
    while (count < n) {
        seq_t x_neg = t_neg * t_neg - (seq_t)1; /* lower integer from negative family */
        seq_t x_pos = t_pos * t_pos;           /* lower integer from positive family */

        if (x_neg <= x_pos) {
            /* Output pair from negative family */
            count++;
            result = x_neg;
            if (count == n) return result;
            count++;
            result = x_neg + (seq_t)1;
            if (count == n) return result;

            /* Advance to the next solution of s² - 2 t² = -1 */
            seq_t t_next = (seq_t)2 * s_neg + (seq_t)3 * t_neg;
            seq_t s_next = (seq_t)3 * s_neg + (seq_t)4 * t_neg;
            t_neg = t_next;
            s_neg = s_next;
        } else {
            /* Output pair from positive family */
            count++;
            result = x_pos;
            if (count == n) return result;
            count++;
            result = x_pos + (seq_t)1;
            if (count == n) return result;

            /* Advance to the next solution of s² - 2 t² = 1 */
            seq_t t_next = (seq_t)2 * s_pos + (seq_t)3 * t_pos;
            seq_t s_next = (seq_t)3 * s_pos + (seq_t)4 * t_pos;
            t_pos = t_next;
            s_pos = s_next;
        }
    }
    return result;   /* should never be reached */
}
